--
-- Table structure for table `wp_rcp_discounts`
--

DROP TABLE IF EXISTS `wp_rcp_discounts`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `wp_rcp_discounts` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `name` tinytext COLLATE utf8mb4_unicode_520_ci NOT NULL,
  `description` longtext COLLATE utf8mb4_unicode_520_ci NOT NULL,
  `amount` tinytext COLLATE utf8mb4_unicode_520_ci NOT NULL,
  `unit` tinytext COLLATE utf8mb4_unicode_520_ci NOT NULL,
  `code` tinytext COLLATE utf8mb4_unicode_520_ci NOT NULL,
  `use_count` mediumint NOT NULL DEFAULT '0',
  `max_uses` mediumint NOT NULL DEFAULT '0',
  `status` tinytext COLLATE utf8mb4_unicode_520_ci NOT NULL,
  `expiration` datetime DEFAULT NULL,
  `membership_level_ids` text COLLATE utf8mb4_unicode_520_ci NOT NULL,
  `one_time` smallint NOT NULL DEFAULT '0',
